function n(t){return Math.round((Number(t)+Number.EPSILON)*100)/100}function u(t){return n(Number(t)*(1+.15))}function o(t){return n(Number(t)*.15)}const a=new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"});function m(t,e="BRL"){const r=Number(t??0);if(!e||e==="BRL")return a.format(r);try{return new Intl.NumberFormat("pt-BR",{style:"currency",currency:e}).format(r)}catch{return`${r.toFixed(2)} ${e}`}}function f(){return[100,500,1e3,5e3].map(t=>({amount:t,fee:o(t),total:u(t)}))}export{o as a,f,m,u as t};
